  section:not(.hero){width:min(1180px,calc(100% - 34px));margin:0 auto;padding:72px 0}.title{text-align:center;margin-bottom:38px}.title h2{font-family:'Playfair Display',serif;font-size:2.35rem;color:var(--teal-dark);margin-bottom:8px}.title p{color:var(--muted);max-width:760px;margin:0 auto;line-height:1.6}
  .features{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:22px}.feature{background:#fff;border-radius:22px;padding:26px;box-shadow:var(--shadow);text-align:center}.feature b{display:inline-flex;width:58px;height:58px;border-radius:18px;background:#e6f6f4;align-items:center;justify-content:center;color:var(--teal-dark);margin-bottom:14px}
  .cottages{display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:24px}.card{background:#fff;border-radius:24px;overflow:hidden;box-shadow:var(--shadow);transition:transform .25s}.card:hover{transform:translateY(-8px)}.media{position:relative;height:220px}.media img{width:100%;height:100%;object-fit:cover}.hover{position:absolute;inset:0;padding:18px;background:linear-gradient(180deg,rgba(8,24,24,.08),rgba(8,24,24,.84));color:#fff;opacity:0;transition:opacity .25s;display:flex;flex-direction:column;justify-content:flex-end}.card:hover .hover{opacity:1}
