  .bottom{display:flex;justify-content:space-between;align-items:center;gap:14px;margin-top:12px}.rate{font-size:1.35rem;font-weight:700;color:var(--teal-dark)}.rate small{font-size:.78rem;color:#869999}.book-btn{background:var(--teal);color:#fff}
