  footer{background:#143f42;color:#fff;text-align:center;padding:18px 16px 64px}.footer-title{font-family:'Playfair Display',serif;font-size:1.15rem;margin-bottom:6px}.footer-sub{font-size:.82rem;color:rgba(255,255,255,.88)}
  .overlay{position:fixed;inset:0;background:rgba(8,22,22,.62);display:none;align-items:center;justify-content:center;z-index:200;padding:20px}.overlay.active{display:flex}
  .modal{width:min(100%,540px);max-height:92vh;overflow:auto;background:#fff;border-radius:24px;box-shadow:0 24px 60px rgba(0,0,0,.22);padding:28px;position:relative}.wide{width:min(100%,780px)}.close{position:absolute;top:12px;right:16px;background:none;border:none;font-size:1.7rem;color:#9aa9a9;cursor:pointer}
