  .grid{display:grid;gap:14px}.grid.two{grid-template-columns:repeat(2,minmax(0,1fr))}.group label{display:block;font-size:.82rem;font-weight:700;color:#4e6666;margin-bottom:6px}.group input,.group select{width:100%;padding:12px 14px;border:1.5px solid #d8e8e7;border-radius:16px;background:#fbfefe;font-size:.94rem;outline:none}
  .layout{display:grid;grid-template-columns:1.2fr .8fr;gap:18px}.side{background:linear-gradient(180deg,rgba(0,150,136,.08),rgba(77,182,172,.03));border:1px solid rgba(0,150,136,.12);border-radius:22px;padding:18px}.box,.qr{background:#fff;border:1px solid #e7f1f0;border-radius:18px;padding:16px;margin-bottom:14px}.value{font-size:1.45rem;font-weight:700;color:var(--teal-dark)}.note{font-size:.82rem;color:#6d8484;line-height:1.6;margin-top:6px}
  .qr{text-align:center}.qr img{width:min(100%,260px);max-height:420px;height:auto;object-fit:contain;margin:0 auto 12px;display:block}.avail{display:inline-flex;padding:10px 14px;border-radius:999px;font-size:.82rem;font-weight:700;background:#edf8f7;color:var(--teal-dark);margin:6px 0 14px}.avail.available{background:#e8f5e9;color:#2e7d32}.avail.unavailable{background:#ffebee;color:#c62828}
  .actions{display:flex;justify-content:flex-end;gap:12px;margin-top:18px}.secondary{background:#f2f6f6;color:#617777}.error,.success{display:none;margin-top:12px;font-size:.84rem;font-weight:700;text-align:center}.error{color:#c62828}.success{color:#2e7d32}
  @media(max-width:1024px){.layout,.features,.contact-grid{grid-template-columns:1fr}.hero{padding:110px 24px 84px;background-size:cover,cover}.hero-wrap{max-width:760px}} @media(max-width:760px){nav{padding:0 18px}.nav-links a:not(.btn){display:none}.grid.two{grid-template-columns:1fr}.bottom{flex-direction:column;align-items:flex-start}.hero{min-height:88vh;padding:104px 18px 70px;background-size:cover,cover}.hero-wrap{max-width:100%}.hero h1{font-size:clamp(2.5rem,11vw,4rem)}}
