the total.</div></div><div class="box"><div style="font-size:.84rem;color:#6d8484;margin-bottom:6px">Required Down Payment</div><div class="value" id="guest-down-payment">PHP 0</div><div class="note">Guest bookings show a 30% down payment reference for staff verification.</div></div><div class="qr"><img src="<?= $gcashQrAsset ?>" alt="GCash QR"><strong style="display:block;color:var(--teal-dark);margin-bottom:6px">GCash QR</strong><div class="note">Scan after placing the reservation. The down payment amount is saved with your booking details.</div></div></div></div></div></div>

<script>
let cottages=[],heroIndex=0,heroTimer=null,guestAvailable=false;
async function fetchJson(url, options={}){const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),8000);try{const res=await fetch(url,{cache:'no-store',...options,signal:controller.signal});const text=await res.text();return JSON.parse(text)}finally{clearTimeout(timeout)}}
function openModal(type){document.getElementById(type+'-modal').classList.add('active')}
function closeModal(type){document.getElementById(type+'-modal').classList.remove('active')}
function money(v){return 'PHP '+Number(v||0).toLocaleString()}
function selectedCottage(){const id=Number(document.getElementById('guest-cottage').value);return cottages.find(c=>Number(c.id)===id)||null}
function setAvailability(ok,msg){const el=document.getElementById('guest-availability');const btn=document.getElementById('guest-book-btn');guestAvailable=ok;el.textContent=msg;el.className='avail'+(msg?(' '+(ok?'available':'unavailable')):'');btn.disabled=!ok}
function fillCottageOptions(preId=null){const select=document.getElementById('guest-cottage');const target=preId||Number(select.value)||(cottages[0]?Number(cottages[0].id):0);select.innerHTML=cottages.map(c=>`<option value="${c.id}" ${Number(c.id)===Number(target)?'selected':''}>${c.name} - ${money(c.price)} / ${c.pricing_unit}</option>`).join('')}
function updateDots(){document.getElementById('dots').innerHTML=cottages.slice(0,5).map((_,i)=>`<span class="dot ${i===heroIndex?'active':''}"></span>`).join('')}
function showSlide(i){if(!cottages.length)return;heroIndex=i%cottages.length;document.getElementById('hero').style.setProperty('--hero-image',`url('${(cottages[heroIndex].image_url||'').replace(/'/g,"%27")}')`);updateDots()}
function startSlider(){if(heroTimer)clearInterval(heroTimer);if(!cottages.length)return;showSlide(0);heroTimer=setInterval(()=>showSlide((heroIndex+1)%cottages.length),4200)}
function initDates(){const now=new Date(),tom=new Date(now);tom.setDate(tom.getDate()+1);const d1=now.toISOString().split('T')[0],d2=tom.toISOString().split('T')[0];const inEl=document.getElementById('guest-checkin-date'),outEl=document.getElementById('guest-checkout-date');inEl.min=d1;outEl.min=d2;if(!inEl.value)inEl.value=d1;if(!outEl.value)outEl.value=d2}
function updateGuestSummary(){const c=selectedCottage(),total=document.getElementById('guest-total'),down=document.getElementById('guest-down-payment'),meta=document.getElementById('guest-total-meta');if(!c){total.textContent='PHP 0';down.textContent='PHP 0';meta.textContent='Choose a cottage and stay dates to compute the total.';return}const start=new Date(document.getElementById('guest-checkin-date').value),end=new Date(document.getElementById('guest-checkout-date').value);let units=Math.max(1,Math.round((end-start)/86400000));if(c.pricing_unit==='event')units=1;const grand=Number(c.price)*units;total.textContent=money(grand);down.textContent=money(grand*.3);meta.textContent=`${units} ${c.pricing_unit}${units===1?'':'s'} x ${money(c.price)} | Capacity ${c.capacity} guests`}
async function checkGuestAvailability(){const c=selectedCottage();if(!c){setAvailability(false,'Please choose a cottage first.');return}setAvailability(false,'Checking availability...');const fd=new FormData();fd.append('action','availability');fd.append('cottage_id',c.id);fd.append('check_in',document.getElementById('guest-checkin-date').value);fd.append('check_out',document.getElementById('guest-checkout-date').value);fd.append('guest_count',document.getElementById('guest-count').value);const res=await fetch('reservations.php',{method:'POST',body:fd});const data=await res.json();if(!data.success){setAvailability(false,data.message||'Unable to check availability.');return}setAvailability(!!data.available,data.message)}
function openGuestModal(cottageId=null){fillCottageOptions(cottageId);initDates();document.getElementById('guest-book-error').style.display='none';document.getElementById('guest-book-success').style.display='none';updateGuestSummary();checkGuestAvailability();openModal('guest')}
async function submitGuestBooking(){const err=document.getElementById('guest-book-error'),ok=document.getElementById('guest-book-success');err.style.display='none';ok.style.display='none';await checkGuestAvailability();if(!guestAvailable){err.textContent='Selected dates are unavailable for this cottage.';err.style.display='block';return}const c=selectedCottage();const fd=new FormData();fd.append('action','book_guest');fd.append('cottage_id',c.id);fd.append('guest_name',document.getElementById('guest-name').value);fd.append('guest_phone',document.getElementById('guest-phone').value);fd.append('guest_email',document.getElementById('guest-email').value);fd.append('guest_count',document.getElementById('guest-count').value);fd.append('check_in',document.getElementById('guest-checkin-date').value);fd.append('check_in_time',document.getElementById('guest-checkin-time').value);fd.append('check_out',document.getElementById('guest-checkout-date').value);fd.append('check_out_time',document.getElementById('guest-checkout-time').value);const res=await fetch('reservations.php',{method:'POST',body:fd});const data=await res.json();if(!data.success){err.textContent=data.message||'Guest booking failed.';err.style.display='block';return}ok.textContent=`${data.message} Booking ID: ${data.booking_id}. Down payment: ${money(data.down_payment)}.`;ok.style.display='block'}
async function doLogin(){const err=document.getElementById('login-error');err.style.display='none';const fd=new FormData();fd.append('action','login');fd.append('email',document.getElementById('login-email').value);fd.append('password',document.getElementById('login-password').value);const res=await fetch('auth.php',{method:'POST',body:fd});const data=await res.json();if(!data.success){err.textContent=data.message||'Login failed.';err.style.display='block';return}window.location.href=data.redirect}
async function doRegister(){const err=document.getElementById('register-error'),ok=document.getElementById('register-success');err.style.display='none';ok.style.display='none';const fd=new FormData();fd.append('action','register');fd.append('full_name',document.getElementById('reg-name').value);fd.append('phone',document.getElementById('reg-phone').value);fd.append('email',document.getElementById('reg-email').value);fd.append('password',document.getElementById('reg-password').value);fd.append('confirm_password',document.getElementById('reg-confirm').value);const res=await fetch('auth.php',{method:'POST',body:fd});const data=await res.json();if(!data.success){err.textContent=data.message||'Registration failed.';err.style.display='block';return}ok.textContent='Account created successfully. You can sign in now.';ok.style.display='block'}
function renderCottages(){const container=document.getElementById('cottages-container');if(!cottages.length){container.innerHTML='<div style="grid-column:1/-1;text-align:center;color:#7d9292;padding:40px 10px">No cottages available right now.</div>';return}container.innerHTML=cottages.map(c=>{const amenities=(c.amenities||'').split(',').map(v=>v.trim()).filter(Boolean);return `<article class="card"><div class="media"><img src="${c.image_url}" alt="${c.name}" onerror="this.src='assets/cottages/paradise-nook-cottage.jpg'"><div class="hover"><h4>${c.name}</h4><p>${c.description||'A tropical stay designed for comfort and easy resort access.'}</p><div class="badges"><span>${c.type}</span><span>${c.capacity} guests</span>${amenities.slice(0,3).map(item=>`<span>${item}</span>`).join('')}</div></div></div><div class="info"><h3>${c.name}</h3><p>${c.description||'A tropical stay designed for comfort and easy resort access.'}</p><div class="meta"><span class="pill">${c.type}</span><span>Capacity: <strong>${c.capacity}</strong></span></div><div class="bottom"><div class="rate">${money(c.price)} <small>/ ${c.pricing_unit}</small></div><button class="btn book-btn" type="button" onclick="openGuestModal(${c.id})">Book as Guest</button></div></div></article>`}).join('')}
async function loadCottages(){const container=document.getElementById('cottages-container');try{const data=await fetchJson('cottages.php?action=list');if(!data.success||!Array.isArray(data.cottages)){throw new Error(data.error||data.message||'Could not load cottages.')}cottages=data.cottages;renderCottages();fillCottageOptions();initDates();updateGuestSummary();checkGuestAvailability();startSlider()}catch(e){console.error('Homepage cottage load failed',e);container.innerHTML='<div style="grid-column:1/-1;text-align:center;color:#7d9292;padding:40px 10px">Could not load cottages. Please make sure MySQL is running.</div>'}}
['guest-cottage','guest-count','guest-checkin-date','guest-checkout-date','guest-checkin-time','guest-checkout-time'].forEach(id=>document.addEventListener('change',e=>{if(e.target&&e.target.id===id){if(id==='guest-checkin-date'){const v=document.getElementById('guest-checkin-date').value;if(v){const next=new Date(v);next.setDate(next.getDate()+1);document.getElementById('guest-checkout-date').min=next.toISOString().split('T')[0];if(document.getElementById('guest-checkout-date').value<=v){document.getElementById('guest-checkout-date').value=next.toISOString().split('T')[0]}}}updateGuestSummary();checkGuestAvailability()}}))
document.querySelectorAll('.overlay').forEach(el=>el.addEventListener('click',e=>{if(e.target===el)el.classList.remove('active')}));document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.overlay.active').forEach(el=>el.classList.remove('active'))})
loadCottages();
</script>
</body>
</html>
